/** Only run on client */
import type { FuncSchemas } from "./schemas.js";

/** Read a text/event-stream response and yield the payload of each `data:` event. */
async function* readEventStream(response: Response): AsyncGenerator<string> {
	// If the response has no body: there is nothing to read.
	if (!response.body) return;
	const reader = response.body.pipeThrough(new TextDecoderStream()).getReader();
	let buffer = "";
	/** Parse a raw event into its payload, or null when it has no `data:` line. */
	const parseEvent = (event: string) => {
		if (!event.startsWith("data: ")) return null;
		const payload = event.slice(6);
		// If the payload is valid JSON: use the parsed value, otherwise keep the raw text.
		try {
			const parsed = JSON.parse(payload);
			return typeof parsed === "string" ? parsed : payload;
		} catch {
			return payload;
		}
	};
	try {
		while (true) {
			const { done, value } = await reader.read();
			// If the stream ended: flush any remaining event.
			if (done) {
				const last = parseEvent(buffer);
				if (last !== null) yield last;
				break;
			}
			buffer += value;
			const events = buffer.split("\n\n");
			buffer = events.pop() ?? "";
			for (const event of events) {
				const payload = parseEvent(event);
				if (payload !== null) yield payload;
			}
		}
	} finally {
		// Close the connection if the caller stops early.
		await reader.cancel().catch(() => {});
	}
}

/** Use functions */
export async function useFunc<K extends keyof FuncSchemas>(functionName: K, apiLoad: FuncSchemas[K]["in"], skipSleepTime = true): Promise<FuncSchemas[K]["out"]> {
	// check if it's a form post, if yes set headers to empty
	const isFormData = (apiLoad as any) instanceof FormData;
	const headers: { [key: string]: any } = isFormData ? {} : ({ "Content-Type": "application/json" } as any);
	const body = (isFormData ? apiLoad : JSON.stringify(apiLoad)) as string | FormData;
	// send request and catch any error
	try {
		const requestStartTime = Date.now();
		const request = await fetch("/api/functions", { method: "POST", headers: { ...headers, functionName }, body });
		// check if response is a text/event-stream
		const contentType: "text/event-stream" | "application/json" = request.headers.get("content-type") as any;
		if (contentType === "text/event-stream") {
			const response = { error: false, data: readEventStream(request) as any };
			return response;
		}
		// if request finish under 500 milliseconds: wait one second for better UX
		if (!skipSleepTime) {
			const elapsedTime = Date.now() - requestStartTime;
			const minWaitTime = 300;
			if (elapsedTime < minWaitTime) await new Promise((resolve) => setTimeout(resolve, minWaitTime - elapsedTime));
		}
		// return json
		const response = (await request.json()) as any;
		return response;
	} catch (err: any) {
		// return error
		const response = { error: true as const, data: err.message as string };
		return response;
	}
}

/** Only run on server to avoid loading zod to client */
import { z } from "zod";
import type { RequestEvent } from "@sveltejs/kit";

/** Function schemas */
export const functionsSchemas = {
	toggleDarkMode: {
		in: z.object().nullish(),
		out: z.object({ isDarkMode: z.boolean() }),
		isPublic: true,
	},
	userCreate: {
		in: z.object({ email: z.email() }),
		out: z.string(),
		isPublic: true,
	},
	userDelete: {
		in: z.object({ email: z.email() }),
		out: z.string(),
		isPublic: true,
	},
	userDeletePrivate: {
		in: z.object({ email: z.email() }),
		out: z.string(),
		isPublic: false,
	},
	fileUpload: {
		in: z.custom<FormData>((value) => value instanceof FormData),
		out: z.object({ name: z.string(), size: z.number(), type: z.string() }),
		isPublic: true,
	},
	textStream: {
		in: z.object({ prompt: z.string().min(1) }),
		out: z.custom<AsyncGenerator<string>>(() => true),
		isPublic: true,
	},
};

/** Function schemas type */
export type FuncSchemas = {
	[K in keyof typeof functionsSchemas]: {
		in: z.infer<(typeof functionsSchemas)[K]["in"]>;
		out: { error: true; data: string } | { error: false; data: z.infer<(typeof functionsSchemas)[K]["out"]> };
		isPublic?: boolean;
	};
};

/** Function response type */
export type FuncResponse<K extends keyof FuncSchemas> = { error: true; data: string } | { error: false; data: z.infer<(typeof functionsSchemas)[K]["out"]> };

/** Type helper to create function response */
export type FuncHandler<K extends keyof FuncSchemas> = (props: {
	event: Omit<RequestEvent, "request"> & {
		request: Omit<RequestEvent["request"], "json"> & {
			json: () => Promise<FuncSchemas[K]["in"]>;
		};
	};
	inputData: FuncSchemas[K]["in"];
}) => FuncSchemas[K]["out"] | Promise<FuncSchemas[K]["out"]> | Promise<Response> | Response;

/** Function response data type */
export type FunctionHookErrorResData = { error: true; data: string };

/** Only run on server */
import { z } from "zod";
import { functionsSchemas } from "./schemas.js";
import type { RequestHandler } from "@sveltejs/kit";
import type { FuncSchemas, FunctionHookErrorResData } from "./schemas.js";

const moduleFiles = import.meta.glob("#lib/functions/handlers/*.ts", { eager: true });
const handlers: Record<keyof FuncSchemas, Function> = {} as Record<keyof FuncSchemas, Function>;
const functions: (keyof FuncSchemas)[] = [];
// Loop all functions exported by file
for (const handlerModule of Object.values(moduleFiles)) {
	// handlerModule is an object with multiple exported functions
	if (handlerModule && typeof handlerModule === "object") {
		// Get all exported functions from this module
		for (const [exportName, exportedFunction] of Object.entries(handlerModule)) {
			// Only add if it's actually a function
			if (typeof exportedFunction === "function") {
				handlers[exportName as keyof FuncSchemas] = exportedFunction;
				functions.push(exportName as keyof FuncSchemas);
			}
		}
	}
}

/** Convert zod error to string */
const convertZodErrorToString = (functionName: keyof FuncSchemas, error: z.ZodError) => {
	const errors: { message: string; path: string[] }[] = JSON.parse(error.message);
	return errors.map((err) => `${err.message} from function '${functionName}' field '${err.path[0]}'`).join("\n");
};

/** Handle all request to this POST server endpoint */
const POST: RequestHandler = async (event) => {
	const functionName = event.request.headers.get("functionName") as null | keyof FuncSchemas;

	// Check if functionName header was provided
	if (!functionName) {
		const response = { error: true as const, data: "header 'functionName' it's required" as string };
		return Response.json(response);
	}

	// Check if function exists was exported from folder handlers
	if (!(functionName in handlers)) {
		const error: FunctionHookErrorResData = { error: true, data: `Function '${functionName}' does not exists` };
		return Response.json(error);
	}

	// Check if current request to function is permitted (if not public and no user data)
	if (!functionsSchemas[functionName].isPublic && !event.locals.userData) {
		const error: FunctionHookErrorResData = { error: true, data: `Function '${functionName}' is not a public function. If public, set it inside schema using isPublic:true.` };
		return Response.json(error);
	}

	// Validate input data (we do it on the server side to avoid importing zod to the client)
	const isFormData = (functionsSchemas[functionName].in.def.type as string) === "custom";
	const request = event.request.clone();
	const inputData = await request[isFormData ? "formData" : "json"]();
	const parseRes = functionsSchemas[functionName].in.safeParse(inputData);
	// If not validated, return error
	if (!parseRes.success) {
		const error = convertZodErrorToString(functionName, parseRes.error);
		const response = { error: true, data: error };
		return Response.json(response);
	}

	// Handle function
	const handlerResponse = handlers[functionName]({ event, inputData });
	const outputData: FuncSchemas[typeof functionName]["out"] = !(handlerResponse instanceof Promise) ? handlerResponse : await handlerResponse;

	// If returning raw response: return it as it's
	if (outputData instanceof Response) return outputData;
	const headers = new Headers({ "content-type": "application/json" });

	// if not returning error: validate output
	if (!outputData.error) {
		const parseRes = functionsSchemas[functionName]["out"].safeParse(outputData.data);
		// if output was not validated: return error
		if (!parseRes.success) {
			const error = convertZodErrorToString(functionName, parseRes.error);
			return new Response(JSON.stringify({ error: true, data: error }), { headers });
		}
	}

	const response = new Response(JSON.stringify(outputData), { headers });
	return response;
};

export { POST, functions };

import { dev } from "$app/env";
import type { FuncHandler } from "#lib/functions/schemas.js";

/** Toggle theme */
export const toggleDarkMode: FuncHandler<"toggleDarkMode"> = async ({ event }) => {
	const isDarkMode = event.cookies.get("theme") === "dark";
	const theme = isDarkMode ? "light" : "dark";
	// Save the theme for a week; only send it over https outside dev
	event.cookies.set("theme", theme, { path: "/", httpOnly: true, sameSite: "lax", secure: !dev, maxAge: 60 * 60 * 24 * 7 });
	return { error: false, data: { isDarkMode: !isDarkMode } };
};

import type { FuncHandler } from "#lib/functions/schemas.js";

/** Create user */
export const userCreate: FuncHandler<"userCreate"> = async ({ event, inputData }) => {
	const email = inputData.email;
	// This is pointless since input data gets checked before getting here
	if (!email) return { error: true, data: "Please provide user's email." };
	// Create user and return message
	return { error: false, data: `User with email ${email} created.` };
};

/** Delete user */
export const userDelete: FuncHandler<"userDelete"> = async ({ event, inputData }) => {
	const email = inputData.email;
	// This is pointless since input data gets checked before getting here
	if (!email) return { error: true, data: "Please provide user's email." };
	// Create user and return message
	return { error: false, data: `User with email ${email} deleted.` };
};

/** Delete user */
export const userDeletePrivate: FuncHandler<"userDeletePrivate"> = async ({ event, inputData }) => {
	const email = inputData.email;
	// This is pointless since input data gets checked before getting here
	if (!email) return { error: true, data: "Please provide user's email." };
	// Create user and return message
	return { error: false, data: `User with email ${email} deleted.` };
};

/** Read an uploaded file from form data */
export const fileUpload: FuncHandler<"fileUpload"> = async ({ inputData }) => {
	const file = inputData.get("file");
	// If no file was sent: return an error.
	if (!(file instanceof File) || !file.size) return { error: true, data: "Please choose a file to upload." };
	// Return the file details without saving the file
	return { error: false, data: { name: file.name, size: file.size, type: file.type || "unknown" } };
};

/** Stream a reply one word at a time */
export const textStream: FuncHandler<"textStream"> = async ({ inputData }) => {
	const words = `You said "${inputData.prompt}". This reply is streamed from the server one word at a time.`.split(" ");
	const encoder = new TextEncoder();
	const stream = new ReadableStream({
		async start(controller) {
			// Send each word as a server-sent event, then close the stream
			for (const word of words) {
				controller.enqueue(encoder.encode(`data: ${JSON.stringify(`${word} `)}\n\n`));
				await new Promise((resolve) => setTimeout(resolve, 80));
			}
			controller.close();
		},
	});
	return new Response(stream, { headers: { "content-type": "text/event-stream" } });
};
